// Verify the signed RAIOC event before mode can influence routing.
const crypto = require('crypto');
const incoming = $input.first().json;
const body = incoming.body || incoming;
const headers = incoming.headers || {};
const signature = headers['x-n8n-signature'] || headers['X-N8N-Signature'];
const signingSecret = $env.N8N_OUTBOUND_SECRET || $env.N8N_WEBHOOK_SECRET || $env.RAIOC_N8N_WEBHOOK_SECRET;

let signatureValid = false;
if (typeof signingSecret === 'string' && signingSecret.length > 0 && typeof signature === 'string') {
  const expectedSignature = `sha256=${crypto.createHmac('sha256', signingSecret).update(JSON.stringify(body)).digest('hex')}`;
  signatureValid = signature.length === expectedSignature.length &&
    crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expectedSignature));
}

const lead = body.data?.lead || {};
const name = typeof lead.name === 'string' && lead.name.trim() ? lead.name.trim() : null;
const email = typeof lead.email === 'string' && lead.email.trim() ? lead.email.trim().toLowerCase() : null;
const phone = typeof lead.phone === 'string' && lead.phone.trim() ? lead.phone.trim() : null;
const suppliedBudget = Number(lead.budget_aed ?? lead.propertyPriceAed);
const budgetAed = Number.isFinite(suppliedBudget) && suppliedBudget > 0 ? suppliedBudget : null;
const targetAsset = typeof lead.target_asset === 'string' && lead.target_asset.trim() ? lead.target_asset.trim() : null;
const runtimeMode = signatureValid && typeof body.runtime?.mode === 'string' ? body.runtime.mode : null;

let boundary;
if (!signatureValid) {
  boundary = { completed: false, allowExternalFanout: false, httpStatus: 401, reason: 'SIGNATURE_INVALID' };
} else if (runtimeMode === 'canary') {
  boundary = { completed: true, allowExternalFanout: false, httpStatus: 200, reason: 'CANARY_BOUNDARY_COMPLETED' };
} else if (runtimeMode === 'active') {
  boundary = { completed: false, allowExternalFanout: true, httpStatus: 200, reason: 'ACTIVE_REQUIRES_SCORE_VALIDATION' };
} else {
  boundary = { completed: false, allowExternalFanout: false, httpStatus: 400, reason: 'RUNTIME_MODE_INVALID' };
}

return [{
  json: {
    correlation_id: body.correlationId || headers['x-correlation-id'] || null,
    traceparent: headers.traceparent || null,
    runtime: { mode: runtimeMode },
    boundary,
    data: {
      lead: {
        name,
        email,
        phone,
        budget_aed: budgetAed,
        target_asset: targetAsset,
        company: typeof lead.company === 'string' && lead.company.trim() ? lead.company.trim() : null,
        country: typeof lead.country === 'string' && lead.country.trim() ? lead.country.trim() : null,
        segment: typeof lead.segment === 'string' && lead.segment.trim() ? lead.segment.trim() : null
      }
    }
  }
}];

// Scores authorize active-only fan-out, so absent, non-numeric, or below-threshold values fail closed.
const normalized = $('2. Verify & Normalize Signed Event').item.json;
const mark = $input.first().json;
const diraScore = Number(mark.body?.diraScore ?? mark.diraScore);
const riisScore = Number(mark.body?.riisScore ?? mark.riisScore);
const scoresValid = Number.isFinite(diraScore) && Number.isFinite(riisScore) && diraScore >= 80 && riisScore >= 80;

return [{
  json: {
    ...normalized,
    assessment: { diraScore, riisScore },
    boundary: scoresValid
      ? { completed: false, allowExternalFanout: true, httpStatus: 200, reason: 'ACTIVE_SCORES_VALID' }
      : { completed: false, allowExternalFanout: false, httpStatus: 422, reason: 'DIRA_OR_RIIS_INVALID' }
  }
}];

// Canary, invalid-mode, invalid-signature, and invalid-score paths terminate here without provider fan-out.
const boundary = $json.boundary;
return [{ json: { runtime: $json.runtime, boundary } }];

// This runs only after every active-path internal operation and provider fan-out completed.
const normalized = $('2. Verify & Normalize Signed Event').item.json;
return [{
  json: {
    runtime: normalized.runtime,
    boundary: { completed: true, allowExternalFanout: true, httpStatus: 200, reason: 'ACTIVE_PATH_COMPLETED' }
  }
}];
